  private dealtMult = readSetting(DEALT_KEY, 1);
  private takenMult = readSetting(TAKEN_KEY, 1);
  private autoMeleeAim = (() => { try { return localStorage.getItem(AUTO_MELEE_AIM_KEY) === "1"; } catch { return false; } })();
